// Actual utility-process settings/secrets across immutable updates and recovery.
const {app,utilityProcess,safeStorage}=require('electron'),fs=require('node:fs/promises'),path=require('node:path'),assert=require('node:assert/strict');
const config=require(process.argv[2]);app.setPath('userData',path.join(config.directory,'user-data'));
app.whenReady().then(async()=>{
 const {PluginManager}=require('../../electron/plugins/manager.cjs'),{ExtensionRuntime}=require('../../electron/plugins/extensionRuntime.cjs'),manager=new PluginManager(path.join(config.directory,'plugins'),'2.0.0'),host=new ExtensionRuntime({manager,utilityProcess,safeStorage}),checks=[];
 const check=name=>checks.push(name),storage=path.join(manager.root,'.extensions','test.storage'),settingsFile=path.join(storage,'settings.json'),secretFile=path.join(storage,'secrets.json');
 const source=async(version,supported)=>{
  await fs.writeFile(path.join(config.source,'plugin.json'),JSON.stringify({id:'test.storage',name:'Storage lifecycle fixture',publisher:'Test',version,apiVersion:1,main:'dist/extension.cjs',activationEvents:['startup'],contributes:{commands:[{id:'read',name:'Read'},{id:'write',name:'Write'}]}}));
  await fs.writeFile(path.join(config.source,'dist/extension.cjs'),`exports.activate=async c=>{const state=await c.configuration.get('state');if(state&&state.schema>${supported})throw Error('Unsupported newer storage schema');await c.commands.register('read',async()=>({state:await c.configuration.get('state')??null,hasSecret:await c.secrets.get('token')==='fixture-only'}));await c.commands.register('write',async input=>{await c.configuration.update({key:'state',value:input});await c.secrets.store({key:'token',value:'fixture-only'});return true;});};`);
  return (await manager.install(config.source,true)).find(row=>row.manifest.version===version).key;
 };
 try{
  const first=await source('0.1.0',1);await host.trust(first);await host.start(first);await host.execute('test.storage.write',{schema:1,note:'Keep this preference'});const secretBytes=await fs.readFile(secretFile);assert.ok(!secretBytes.toString().includes('fixture-only'));await host.stop(first);check('settings are separate JSON and secret bytes are encrypted');
  const second=await source('0.2.0',2);await assert.rejects(host.start(second),/trust/);await host.trust(second);await host.start(second);assert.deepEqual(await host.execute('test.storage.read'),{state:{schema:1,note:'Keep this preference'},hasSecret:true});check('new immutable version requires its own trust and retains the ID-scoped state');
  await host.execute('test.storage.write',{schema:2,note:'Keep this preference',extra:true});await host.stop(second);const settingsBytes=await fs.readFile(settingsFile);assert.deepEqual(await fs.readFile(secretFile),secretBytes);check('author-owned schema migration preserves the secret and unrelated values');
  await manager.setEnabled(first,true);await assert.rejects(host.start(first),/Unsupported newer storage schema/);assert.deepEqual(await fs.readFile(settingsFile),settingsBytes);assert.deepEqual(await fs.readFile(secretFile),secretBytes);check('rollback can refuse newer author data without rewriting or deleting it');
  await manager.remove(first);await manager.remove(second);assert.deepEqual(await manager.inventory(),[]);assert.deepEqual(await fs.readFile(settingsFile),settingsBytes);assert.deepEqual(await fs.readFile(secretFile),secretBytes);check('uninstall removes payloads and inventory while retaining Node settings and secrets');
  const restored=await source('0.2.0',2);assert.equal(restored,second);await host.start(restored);assert.deepEqual(await host.execute('test.storage.read'),{state:{schema:2,note:'Keep this preference',extra:true},hasSecret:true});await host.stop(restored);check('exact reinstall retains its exact trust and stored state');
  await fs.writeFile(path.join(manager.root,'inventory.json'),'{broken');const review=await manager.prepareRecovery();await manager.recover(review.token);await host.activate('startup');assert.equal(host.active.size,0);await assert.rejects(host.start(restored),/disabled|unavailable/);assert.deepEqual(await fs.readFile(settingsFile),settingsBytes);assert.deepEqual(await fs.readFile(secretFile),secretBytes);check('inventory reconstruction stays disabled and never resets Node data');
  await manager.setEnabled(restored,true);await host.start(restored);assert.equal((await host.execute('test.storage.read')).hasSecret,true);await host.stop(restored);check('explicit recovery activation reads the retained encrypted credential');
  await host.dispose();await fs.writeFile(path.join(config.directory,'result.json'),JSON.stringify({ok:true,checks},null,2));app.exit(0);
 }catch(error){await host.dispose();throw error;}
}).catch(error=>{console.error(error);app.exit(1);});
